(()=>{'use strict';let pending=false;function mark(){document.querySelectorAll('#main-content .pati-follow-person button[data-action="follow"]').forEach(btn=>{btn.classList.toggle('buchee-follow-back-list',btn.textContent.trim().toLocaleLowerCase('tr-TR')==='sen de takip et')})}function schedule(){if(pending)return;pending=true;requestAnimationFrame(()=>{pending=false;mark()})}function start(){mark();const root=document.getElementById('main-content');if(root)new MutationObserver(schedule).observe(root,{childList:true,subtree:true,characterData:true})}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start()})();